import{_ as c,c as p,a1 as i,b as s,w as t,a2 as n,j as d,a,B as h,o,E as l}from"./chunks/framework.CnnR69hl.js";const P=JSON.parse('{"title":"Networking Fundamentals — সম্পূর্ণ বাংলা গাইড","description":"Hosts, IP Address, Network, Subnet ও Internet কীভাবে কাজ করে তার গভীর বাংলা গাইড।","frontmatter":{"title":"Networking Fundamentals — সম্পূর্ণ বাংলা গাইড","description":"Hosts, IP Address, Network, Subnet ও Internet কীভাবে কাজ করে তার গভীর বাংলা গাইড।"},"headers":[],"relativePath":"networking-fundamentals/what-is-a-network.md","filePath":"networking-fundamentals/what-is-a-network.md"}'),u={name:"networking-fundamentals/what-is-a-network.md"};function k(g,e,b,m,A,w){const r=h("Mermaid");return o(),p("div",null,[e[7]||(e[7]=i('<h1 id="networking-fundamentals-—-hosts-ip-address-network-ও-internet" tabindex="-1">Networking Fundamentals — Hosts, IP Address, Network ও Internet <a class="header-anchor" href="#networking-fundamentals-—-hosts-ip-address-network-ও-internet" aria-label="Permalink to &quot;Networking Fundamentals — Hosts, IP Address, Network ও Internet&quot;">​</a></h1><p>কম্পিউটার Networking বোঝার শুরুটা কোনো নির্দিষ্ট device বা command দিয়ে নয়; শুরু হয় চারটি মৌলিক ধারণা দিয়ে: <strong>Host</strong>, <strong>IP Address</strong>, <strong>Network</strong>, এবং <strong>Internet</strong>। এই চারটি ধারণা পরিষ্কার হলে পরের অধ্যায়ের <code>Switch</code>, <code>Router</code>, <code>TCP</code>, <code>DNS</code>, <code>HTTP</code>, <code>Firewall</code> এবং container networking অনেক সহজে বোঝা যায়।</p><p>এই page-এ আমরা সাধারণ computer networking নিয়ে আলোচনা করব। এখানে কোনো নির্দিষ্ট cloud provider-এর architecture নয়; বরং Internet-এ data কীভাবে এক host থেকে অন্য host-এ পৌঁছায়, সেই ভিত্তিটা তৈরি করা হবে।</p><h2 id="_1-what-—-network-কী" tabindex="-1">1. What — Network কী? <a class="header-anchor" href="#_1-what-—-network-কী" aria-label="Permalink to &quot;1. What — Network কী?&quot;">​</a></h2><p><strong>Network</strong> হলো দুই বা ততোধিক <strong>Host</strong>-কে এমনভাবে সংযুক্ত করা একটি logical বা physical ব্যবস্থা, যাতে তারা data আদান-প্রদান করতে পারে।</p><p>এখানে:</p><ul><li><strong>Host</strong> হলো যে কোনো device যা network traffic পাঠাতে বা গ্রহণ করতে পারে।</li><li><strong>IP Address</strong> হলো network-এ কোনো host-এর logical address বা পরিচয়।</li><li><strong>Protocol</strong> হলো data আদান-প্রদানের নিয়ম।</li><li><strong>Network</strong> হলো সেই host ও communication path-এর সংগঠিত সমষ্টি।</li><li><strong>Internet</strong> হলো পরস্পরের সঙ্গে সংযুক্ত অসংখ্য network-এর বিশাল সমষ্টি।</li></ul><p>একটি network খুব ছোট হতে পারে, যেমন cable দিয়ে সরাসরি যুক্ত দুটি computer। আবার খুব বড়ও হতে পারে, যেমন দেশ-বিদেশের ISP, data center এবং backbone network মিলিয়ে Internet।</p>',8)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BHost%3A%20Laptop%5D%20%3C--%3E%7CNetwork%20connection%7C%20B%5BHost%3A%20Server%5D%0A%20%20%20%20C%5BHost%3A%20Phone%5D%20%3C--%3E%7CNetwork%20connection%7C%20D%5BHost%3A%20Smart%20TV%5D%0A%20%20%20%20E%5BLocal%20Network%5D%20--%3E%20F%5BISP%20Network%5D%0A%20%20%20%20F%20--%3E%20G%5BInternet%3A%20Interconnected%20Networks%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=i('<h2 id="_2-why-—-network-কেন-দরকার" tabindex="-1">2. Why — Network কেন দরকার? <a class="header-anchor" href="#_2-why-—-network-কেন-দরকার" aria-label="Permalink to &quot;2. Why — Network কেন দরকার?&quot;">​</a></h2><p>Network না থাকলে প্রতিটি device বিচ্ছিন্ন দ্বীপের মতো থাকত। Data সরাতে হলে storage device হাতে করে এক machine থেকে অন্য machine-এ নিতে হতো।</p><p>Network আমাদের সাহায্য করে:</p><ul><li>একটি device থেকে অন্য device-এ file পাঠাতে</li><li>Web server থেকে webpage বা API response পেতে</li><li>Database, cache ও application server-এর মধ্যে যোগাযোগ করতে</li><li>Video call, online gaming ও streaming চালাতে</li><li>Printer, storage এবং অন্যান্য shared resource ব্যবহার করতে</li><li>Distributed application ও microservice তৈরি করতে</li><li>ML training job, model server ও monitoring service সংযুক্ত করতে</li></ul><p>একটি production application-এ network failure মানেই শুধু Internet বন্ধ হওয়া নয়। Application থেকে database-এ route না থাকা, ভুল IP, blocked port, DNS failure বা packet loss হলেও service অচল হতে পারে।</p><div class="tip custom-block"><p class="custom-block-title">মূল ধারণা</p><p>কোনো application &quot;চলছে না&quot; বলার আগে আলাদা করে ভাবুন: host কি জীবিত, IP configuration ঠিক কি না, route আছে কি না, port শুনছে কি না, এবং application protocol কাজ করছে কি না।</p></div><h2 id="_3-analogy-—-ডাক-ব্যবস্থার-সঙ্গে-তুলনা" tabindex="-1">3. Analogy — ডাক ব্যবস্থার সঙ্গে তুলনা <a class="header-anchor" href="#_3-analogy-—-ডাক-ব্যবস্থার-সঙ্গে-তুলনা" aria-label="Permalink to &quot;3. Analogy — ডাক ব্যবস্থার সঙ্গে তুলনা&quot;">​</a></h2><p>Networking-কে একটি international postal system হিসেবে ভাবুন।</p><table tabindex="0"><thead><tr><th>Networking ধারণা</th><th>ডাক ব্যবস্থায় উপমা</th></tr></thead><tbody><tr><td>Host</td><td>যে বাড়ি বা অফিস চিঠি পাঠায়/গ্রহণ করে</td></tr><tr><td>IP Address</td><td>বাড়ির পূর্ণ ডাক ঠিকানা</td></tr><tr><td>Network</td><td>একই এলাকার ডাক-ব্যবস্থা</td></tr><tr><td>Router</td><td>কোন পথে চিঠি যাবে তা ঠিক করা sorting office</td></tr><tr><td>Packet</td><td>চিঠির একটি খাম</td></tr><tr><td>Port</td><td>একই বাড়ির নির্দিষ্ট room বা service</td></tr><tr><td>Protocol</td><td>চিঠি পাঠানোর format ও নিয়ম</td></tr><tr><td>ISP</td><td>আপনার এলাকার postal carrier</td></tr><tr><td>DNS</td><td>নাম দেখে ঠিকানা খুঁজে বের করা phone book</td></tr><tr><td>Firewall</td><td>নিরাপত্তা প্রহরী, কে ঢুকতে পারবে তা যাচাই করে</td></tr></tbody></table><p>আপনি যদি শুধু &quot;Ashraf&quot; লিখে একটি চিঠি পাঠান, postal system জানবে না সেটি কোথায় যাবে। একইভাবে application যদি সঠিক destination IP বা hostname না জানে, data পাঠাতে পারবে না।</p><h2 id="_4-host-—-network-এর-অংশগ্রহণকারী" tabindex="-1">4. Host — Network-এর অংশগ্রহণকারী <a class="header-anchor" href="#_4-host-—-network-এর-অংশগ্রহণকারী" aria-label="Permalink to &quot;4. Host — Network-এর অংশগ্রহণকারী&quot;">​</a></h2><p><strong>Host</strong> হলো network-এ অংশগ্রহণকারী এমন যেকোনো device যার network identity আছে এবং যে data send বা receive করতে পারে। Host-কে অনেক সময় <strong>end system</strong>-ও বলা হয়, কারণ communication-এর endpoint সাধারণত host-ই।</p><p>উদাহরণ:</p><ul><li>Laptop, desktop ও mobile phone</li><li>Web server, API server ও database server</li><li>Router বা network appliance, যদি সেটি traffic originate বা terminate করে</li><li>Printer, camera, smart speaker ও IoT device</li><li>Virtual machine এবং container</li><li>Kubernetes-এর ভিতরের pod বা service endpoint</li></ul><h3 id="client-ও-server" tabindex="-1">Client ও Server <a class="header-anchor" href="#client-ও-server" aria-label="Permalink to &quot;Client ও Server&quot;">​</a></h3><p><strong>Client</strong> হলো যে host কোনো resource বা service চায়। <strong>Server</strong> হলো যে host request গ্রহণ করে এবং response বা resource দেয়।</p><p>এই ভূমিকা স্থায়ী নয়। একই machine এক সময় client এবং অন্য সময় server হতে পারে। যেমন browser একটি web server-এর client, কিন্তু file share করলে সেই laptop নিজেই server-এর মতো কাজ করতে পারে।</p>',17)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-256",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20Client%20Host%0A%20%20%20%20participant%20S%20as%20Server%20Host%0A%20%20%20%20C-%3E%3ES%3A%20Request%3A%20resource%20%E0%A6%9A%E0%A6%BE%E0%A6%87%0A%20%20%20%20S-%3E%3ES%3A%20Request%20process%20%E0%A6%95%E0%A6%B0%E0%A7%87%0A%20%20%20%20S--%3E%3EC%3A%20Response%3A%20data%20%E0%A6%AA%E0%A6%BE%E0%A6%A0%E0%A6%BE%E0%A6%AF%E0%A6%BC%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=i(`<div class="warning custom-block"><p class="custom-block-title">Client মানেই দুর্বল, Server মানেই শক্তিশালী নয়</p><p>Client ও Server মূলত communication role। Server হিসেবে কাজ করা computer সাধারণ laptop-ও হতে পারে, আর client হিসেবে cloud-এর শক্তিশালী machine-ও থাকতে পারে।</p></div><h2 id="_5-ip-address-—-host-এর-logical-পরিচয়" tabindex="-1">5. IP Address — Host-এর Logical পরিচয় <a class="header-anchor" href="#_5-ip-address-—-host-এর-logical-পরিচয়" aria-label="Permalink to &quot;5. IP Address — Host-এর Logical পরিচয়&quot;">​</a></h2><p><strong>IP Address</strong> বা Internet Protocol Address হলো network-এ কোনো host বা network interface শনাক্ত করার logical address। Data packet-এর source ও destination কোথায়, তা বোঝার জন্য IP Address ব্যবহার করা হয়।</p><p>একটি device-এর একাধিক network interface থাকলে একাধিক IP থাকতে পারে। যেমন laptop-এর Wi-Fi interface এবং Ethernet interface-এর আলাদা IP থাকতে পারে।</p><h3 id="ipv4" tabindex="-1">IPv4 <a class="header-anchor" href="#ipv4" aria-label="Permalink to &quot;IPv4&quot;">​</a></h3><p><strong>IPv4</strong> হলো Internet Protocol-এর বহুল ব্যবহৃত version। IPv4 address মোট <strong>32-bit</strong> এবং সাধারণত চারটি decimal octet হিসেবে লেখা হয়।</p><p>উদাহরণ:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.1.25</span></span></code></pre></div><p>প্রতিটি octet-এর মান <code>0</code> থেকে <code>255</code> পর্যন্ত হতে পারে। তাই মোট address space হলো:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2^32 = 4,294,967,296টি address</span></span></code></pre></div><p>তবে সব address সাধারণ host-কে দেওয়া যায় না। Private range, loopback, multicast, reserved এবং network/broadcast address-এর মতো বিশেষ ব্যবহার আছে।</p><h3 id="ipv6" tabindex="-1">IPv6 <a class="header-anchor" href="#ipv6" aria-label="Permalink to &quot;IPv6&quot;">​</a></h3><p><strong>IPv6</strong> হলো IPv4-এর পরের version। এটি 128-bit address ব্যবহার করে এবং address space অত্যন্ত বড়।</p><p>উদাহরণ:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2001:db8:85a3::8a2e:370:7334</span></span></code></pre></div><p>এই page-এ মূল flow বোঝানোর জন্য IPv4 ব্যবহার করা হবে, কিন্তু production network-এ IPv6-এর উপস্থিতি উপেক্ষা করা উচিত নয়।</p><h3 id="public-ও-private-ip" tabindex="-1">Public ও Private IP <a class="header-anchor" href="#public-ও-private-ip" aria-label="Permalink to &quot;Public ও Private IP&quot;">​</a></h3><p><strong>Private IP</strong> সাধারণত local network-এর ভিতরে ব্যবহৃত হয় এবং Internet-এ সরাসরি routable নয়। IPv4-এর প্রচলিত private range:</p><table tabindex="0"><thead><tr><th>Range</th><th>CIDR</th></tr></thead><tbody><tr><td><code>10.0.0.0</code> – <code>10.255.255.255</code></td><td><code>10.0.0.0/8</code></td></tr><tr><td><code>172.16.0.0</code> – <code>172.31.255.255</code></td><td><code>172.16.0.0/12</code></td></tr><tr><td><code>192.168.0.0</code> – <code>192.168.255.255</code></td><td><code>192.168.0.0/16</code></td></tr></tbody></table><p><strong>Public IP</strong> Internet-এ globally routable address। ISP সাধারণত home router বা organization-এর edge router-কে public IP দেয়।</p><div class="danger custom-block"><p class="custom-block-title">Private IP-কে Public IP ভাববেন না</p><p><code>192.168.x.x</code>, <code>10.x.x.x</code> বা <code>172.16.x.x</code> থেকে <code>172.31.x.x</code> range-এর IP Internet-এ সরাসরি পৌঁছানো যায় না। সাধারণত <code>NAT</code> নামের একটি ব্যবস্থা private host-এর traffic public address দিয়ে বাইরে পাঠায়।</p></div><h2 id="_6-network-ও-subnet" tabindex="-1">6. Network ও Subnet <a class="header-anchor" href="#_6-network-ও-subnet" aria-label="Permalink to &quot;6. Network ও Subnet&quot;">​</a></h2><p>Network হলো logically grouped host-এর সমষ্টি। একই network-এর host সাধারণত পরস্পরের সঙ্গে সরাসরি বা local switching-এর মাধ্যমে যোগাযোগ করতে পারে।</p><p><strong>Subnet</strong> বা subnetworks হলো বড় network-কে ছোট logical network-এ ভাগ করার পদ্ধতি। এর ফলে:</p><ul><li>Broadcast domain ছোট হয়</li><li>Address management সহজ হয়</li><li>আলাদা team বা service isolate করা যায়</li><li>Routing policy পরিষ্কার করা যায়</li><li>Failure ও security boundary নিয়ন্ত্রণ করা যায়</li></ul><p>একটি IPv4 address সাধারণত দুই অংশে দেখা হয়:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network portion + Host portion</span></span></code></pre></div><p>কোন bit network-এর এবং কোন bit host-এর, তা <strong>subnet mask</strong> বা <strong>CIDR prefix</strong> নির্ধারণ করে।</p><p>উদাহরণ:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IP Address: 192.168.1.25</span></span>
<span class="line"><span>Subnet:     192.168.1.0/24</span></span></code></pre></div><p><code>/24</code> মানে প্রথম 24 bit network portion, বাকি 8 bit host portion। এই subnet-এর সাধারণ usable host range হলো <code>192.168.1.1</code> থেকে <code>192.168.1.254</code>; <code>192.168.1.0</code> network address এবং <code>192.168.1.255</code> broadcast address হিসেবে ব্যবহৃত হয়।</p><div class="info custom-block"><p class="custom-block-title">Subnetting-এর গভীরতা</p><p><code>CIDR</code>, subnet calculation, usable host count এবং route summarization আলাদা একটি topic হিসেবে পড়া উচিত। এখানে শুধু network-এর logical grouping বোঝানোর জন্য মৌলিক ধারণাটি দেওয়া হলো।</p></div><h2 id="_7-network-এর-ধরন" tabindex="-1">7. Network-এর ধরন <a class="header-anchor" href="#_7-network-এর-ধরন" aria-label="Permalink to &quot;7. Network-এর ধরন&quot;">​</a></h2><h3 id="pan-—-personal-area-network" tabindex="-1">PAN — Personal Area Network <a class="header-anchor" href="#pan-—-personal-area-network" aria-label="Permalink to &quot;PAN — Personal Area Network&quot;">​</a></h3><p>একজন ব্যক্তির খুব কাছের device-এর ছোট network। Bluetooth headphone ও phone-এর সংযোগ একটি উদাহরণ।</p><h3 id="lan-—-local-area-network" tabindex="-1">LAN — Local Area Network <a class="header-anchor" href="#lan-—-local-area-network" aria-label="Permalink to &quot;LAN — Local Area Network&quot;">​</a></h3><p>বাড়ি, office, lab বা একটি building-এর ভিতরের local network। সাধারণত Ethernet বা Wi-Fi দিয়ে তৈরি হয়।</p><h3 id="wlan-—-wireless-lan" tabindex="-1">WLAN — Wireless LAN <a class="header-anchor" href="#wlan-—-wireless-lan" aria-label="Permalink to &quot;WLAN — Wireless LAN&quot;">​</a></h3><p>Wireless technology, সাধারণত Wi-Fi, ব্যবহার করে তৈরি LAN-কে WLAN বলা হয়।</p><h3 id="man-—-metropolitan-area-network" tabindex="-1">MAN — Metropolitan Area Network <a class="header-anchor" href="#man-—-metropolitan-area-network" aria-label="Permalink to &quot;MAN — Metropolitan Area Network&quot;">​</a></h3><p>একটি শহর বা metropolitan area জুড়ে বিস্তৃত network। একাধিক office বা institution যুক্ত করতে ব্যবহার হতে পারে।</p><h3 id="wan-—-wide-area-network" tabindex="-1">WAN — Wide Area Network <a class="header-anchor" href="#wan-—-wide-area-network" aria-label="Permalink to &quot;WAN — Wide Area Network&quot;">​</a></h3><p>বড় ভৌগোলিক অঞ্চলে বিস্তৃত network। বিভিন্ন city, country বা data center সংযুক্ত করা WAN-এর উদাহরণ।</p><h3 id="internet" tabindex="-1">Internet <a class="header-anchor" href="#internet" aria-label="Permalink to &quot;Internet&quot;">​</a></h3><p>Internet কোনো একক network নয়। এটি ISP, enterprise network, data center network, submarine cable, exchange point এবং backbone network-এর interconnected system।</p><table tabindex="0"><thead><tr><th>Network type</th><th>বিস্তার</th><th>উদাহরণ</th></tr></thead><tbody><tr><td>PAN</td><td>ব্যক্তিগত পরিসর</td><td>Phone ও Bluetooth earbud</td></tr><tr><td>LAN</td><td>বাড়ি/office/building</td><td>Office Ethernet network</td></tr><tr><td>MAN</td><td>শহর</td><td>City-wide institutional network</td></tr><tr><td>WAN</td><td>দেশ/বিশ্ব</td><td>Bank branch network</td></tr><tr><td>Internet</td><td>বিশ্বব্যাপী</td><td>Public web ও API ecosystem</td></tr></tbody></table><h2 id="_8-data-কীভাবে-এক-host-থেকে-অন্য-host-এ-যায়" tabindex="-1">8. Data কীভাবে এক Host থেকে অন্য Host-এ যায়? <a class="header-anchor" href="#_8-data-কীভাবে-এক-host-থেকে-অন্য-host-এ-যায়" aria-label="Permalink to &quot;8. Data কীভাবে এক Host থেকে অন্য Host-এ যায়?&quot;">​</a></h2><p>Application সরাসরি পুরো data একসাথে পাঠায় না। Data সাধারণত ছোট ছোট <strong>packet</strong>-এ ভাগ হয়। Packet হলো network-এর মধ্য দিয়ে চলাচলকারী data-এর একক অংশ, যার সঙ্গে source, destination এবং control information যুক্ত থাকে।</p><p>সাধারণ flow:</p><ol><li>Application data তৈরি করে</li><li>Transport layer data-কে segment বা datagram-এ সাজায়</li><li>Network layer source ও destination IP যোগ করে packet তৈরি করে</li><li>Data Link layer local delivery-এর জন্য frame তৈরি করে</li><li>Physical medium bit হিসেবে data বহন করে</li><li>প্রতিটি intermediate router destination দেখে পরের hop বেছে নেয়</li><li>Destination host packet গ্রহণ করে layers-এর মাধ্যমে data application-এ পৌঁছে দেয়</li></ol>`,50)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-565",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BApplication%20Data%5D%20--%3E%20B%5BTransport%3A%20Segment%5D%0A%20%20%20%20B%20--%3E%20C%5BNetwork%3A%20IP%20Packet%5D%0A%20%20%20%20C%20--%3E%20D%5BData%20Link%3A%20Frame%5D%0A%20%20%20%20D%20--%3E%20E%5BPhysical%3A%20Bits%5D%0A%20%20%20%20E%20--%3E%20F%5BNetwork%20Medium%5D%0A%20%20%20%20F%20--%3E%20G%5BDestination%20Host%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=i('<h3 id="packet-বনাম-circuit" tabindex="-1">Packet বনাম Circuit <a class="header-anchor" href="#packet-বনাম-circuit" aria-label="Permalink to &quot;Packet বনাম Circuit&quot;">​</a></h3><p>Traditional telephone system-এ একটি call-এর জন্য নির্দিষ্ট circuit reserve করা হতো। Internet মূলত <strong>packet switching</strong> ব্যবহার করে: প্রতিটি packet network-এর available path ব্যবহার করে এগোয়। তাই একই connection-এর packet ভিন্ন route-এও যেতে পারে এবং congestion হলে delay বা loss হতে পারে।</p><h2 id="_9-router-ও-interconnected-networks" tabindex="-1">9. Router ও Interconnected Networks <a class="header-anchor" href="#_9-router-ও-interconnected-networks" aria-label="Permalink to &quot;9. Router ও Interconnected Networks&quot;">​</a></h2><p>একটি host যখন নিজের local subnet-এর বাইরের destination-এ data পাঠাতে চায়, তখন সাধারণত <strong>default gateway</strong>-এর কাছে packet পাঠায়। Default gateway হলো local network থেকে বাইরের network-এ যাওয়ার router।</p><p><strong>Router</strong> IP address দেখে packet-এর পরবর্তী গন্তব্য বা <strong>next hop</strong> নির্ধারণ করে। এই সিদ্ধান্ত নেওয়ার জন্য router-এর <strong>routing table</strong> থাকে।</p>',5)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-581",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20H1%5BHost%20A%3Cbr%2F%3E192.168.1.25%5D%20--%3E%20S1%5BLocal%20Switch%5D%0A%20%20%20%20S1%20--%3E%20R1%5BRouter%20A%3Cbr%2F%3EDefault%20Gateway%5D%0A%20%20%20%20R1%20--%3E%20R2%5BISP%20Router%5D%0A%20%20%20%20R2%20--%3E%20R3%5BInternet%20Backbone%20Router%5D%0A%20%20%20%20R3%20--%3E%20S2%5BRemote%20Network%5D%0A%20%20%20%20S2%20--%3E%20H2%5BServer%20B%3Cbr%2F%3E203.0.113.20%5D%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[a(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=i('<p>একটি packet-এর journey-তে:</p><ul><li>Source host destination IP নির্ধারণ করে</li><li>Local subnet কি না যাচাই করে</li><li>Remote হলে default gateway-এর MAC address খুঁজে</li><li>Router packet receive করে routing table দেখে</li><li>Router TTL কমিয়ে পরের interface-এ পাঠায়</li><li>এই process বহু hop পেরিয়ে destination network-এ পৌঁছায়</li></ul><p><strong>Hop</strong> হলো packet-এর এক router বা Layer 3 device থেকে পরের router-এ যাওয়ার একটি ধাপ।</p><h2 id="_10-ip-address-mac-address-ও-port-এর-পার্থক্য" tabindex="-1">10. IP Address, MAC Address ও Port-এর পার্থক্য <a class="header-anchor" href="#_10-ip-address-mac-address-ও-port-এর-পার্থক্য" aria-label="Permalink to &quot;10. IP Address, MAC Address ও Port-এর পার্থক্য&quot;">​</a></h2><p>এই তিনটি address গুলিয়ে ফেলা নতুনদের সাধারণ ভুল।</p><table tabindex="0"><thead><tr><th>বিষয়</th><th>IP Address</th><th>MAC Address</th><th>Port</th></tr></thead><tbody><tr><td>পরিচয়</td><td>Logical network address</td><td>Local interface-এর hardware/data-link address</td><td>Host-এর ভিতরের service/application endpoint</td></tr><tr><td>Layer</td><td>Network layer</td><td>Data Link layer</td><td>Transport layer</td></tr><tr><td>উদাহরণ</td><td><code>192.168.1.25</code></td><td><code>00:1A:2B:3C:4D:5E</code></td><td><code>443</code>, <code>5432</code></td></tr><tr><td>Scope</td><td>Local বা global routing</td><td>সাধারণত local network segment</td><td>নির্দিষ্ট host-এর নির্দিষ্ট service</td></tr><tr><td>পরিবর্তন</td><td>Network বদলালে বদলাতে পারে</td><td>Interface বদলালে বদলায়</td><td>Application configuration অনুযায়ী</td></tr></tbody></table><p>একটি web request-এ:</p><ul><li>IP বলে কোন host-এ যেতে হবে</li><li>MAC বলে local link-এ কোন interface-এ frame যাবে</li><li>Port বলে সেই host-এর কোন service request নেবে</li></ul><h2 id="_11-hands-on-commands" tabindex="-1">11. Hands-on Commands <a class="header-anchor" href="#_11-hands-on-commands" aria-label="Permalink to &quot;11. Hands-on Commands&quot;">​</a></h2><h3 id="নিজের-ip-ও-interface-দেখা" tabindex="-1">নিজের IP ও interface দেখা <a class="header-anchor" href="#নিজের-ip-ও-interface-দেখা" aria-label="Permalink to &quot;নিজের IP ও interface দেখা&quot;">​</a></h3><p>Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> address</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span></span></code></pre></div><p>সম্ভাব্য output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2: eth0: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt;</span></span>\n<span class="line"><span>    inet 192.168.1.25/24 brd 192.168.1.255 scope global eth0</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>default via 192.168.1.1 dev eth0</span></span>\n<span class="line"><span>192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.25</span></span></code></pre></div><p>Windows PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ipconfig</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetIPConfiguration</span></span></code></pre></div><p>এখানে খুঁজবেন:</p><ul><li>Interface-এর নাম</li><li>IPv4 address</li><li>Subnet mask বা prefix</li><li>Default gateway</li><li>DNS server</li></ul><h3 id="connectivity-পরীক্ষা-ping" tabindex="-1">Connectivity পরীক্ষা: <code>ping</code> <a class="header-anchor" href="#connectivity-পরীক্ষা-ping" aria-label="Permalink to &quot;Connectivity পরীক্ষা: `ping`&quot;">​</a></h3><p><code>ping</code> সাধারণত ICMP Echo Request পাঠিয়ে destination থেকে Echo Reply আসে কি না পরীক্ষা করে।</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.8.8.8</span></span></code></pre></div><p>সম্ভাব্য output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=1 ttl=117 time=24.8 ms</span></span>\n<span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=2 ttl=117 time=25.1 ms</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>--- 8.8.8.8 ping statistics ---</span></span>\n<span class="line"><span>4 packets transmitted, 4 received, 0% packet loss</span></span>\n<span class="line"><span>round-trip min/avg/max = 24.8/25.0/25.4 ms</span></span></code></pre></div><p><code>ping</code> সফল হলে অন্তত IP-level reachability সম্পর্কে ধারণা পাওয়া যায়। তবে <code>ping</code> বন্ধ থাকলেও web service সচল থাকতে পারে; কারণ firewall ICMP block করতে পারে।</p><h3 id="route-দেখা-traceroute-ও-tracert" tabindex="-1">Route দেখা: <code>traceroute</code> ও <code>tracert</code> <a class="header-anchor" href="#route-দেখা-traceroute-ও-tracert" aria-label="Permalink to &quot;Route দেখা: `traceroute` ও `tracert`&quot;">​</a></h3><p>Linux/macOS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">traceroute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span></code></pre></div><p>Windows:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tracert </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">example.com</span></span></code></pre></div><p>এগুলো destination-এর পথে intermediate hop দেখানোর চেষ্টা করে। প্রতিটি hop-এর latency ও timeout দেখে কোন অংশে সমস্যা হতে পারে তা অনুমান করা যায়।</p><h3 id="local-neighbor-দেখা-arp-ও-ip-neigh" tabindex="-1">Local neighbor দেখা: <code>arp</code> ও <code>ip neigh</code> <a class="header-anchor" href="#local-neighbor-দেখা-arp-ও-ip-neigh" aria-label="Permalink to &quot;Local neighbor দেখা: `arp` ও `ip neigh`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neigh</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span></code></pre></div><p>এগুলো local network-এ IP থেকে MAC mapping-এর cache দেখাতে পারে। এই mapping তৈরিতে IPv4-এর <strong>ARP (Address Resolution Protocol)</strong> ব্যবহৃত হয়।</p><h3 id="open-port-দেখা-ss-ও-netstat" tabindex="-1">Open port দেখা: <code>ss</code> ও <code>netstat</code> <a class="header-anchor" href="#open-port-দেখা-ss-ও-netstat" aria-label="Permalink to &quot;Open port দেখা: `ss` ও `netstat`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tuln</span></span></code></pre></div><p>Windows:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">netstat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ano</span></span></code></pre></div><p>এখানে local address, port, protocol এবং connection state দেখা যায়। Port listening আছে মানেই application সঠিকভাবে request process করছে, এমন নয়; এটি কেবল একটি স্তরের প্রমাণ।</p><h2 id="_12-internal-working-—-একটি-সাধারণ-request-এর-ধাপ" tabindex="-1">12. Internal Working — একটি সাধারণ request-এর ধাপ <a class="header-anchor" href="#_12-internal-working-—-একটি-সাধারণ-request-এর-ধাপ" aria-label="Permalink to &quot;12. Internal Working — একটি সাধারণ request-এর ধাপ&quot;">​</a></h2><p>ধরা যাক, <code>192.168.1.25</code> host থেকে <code>203.0.113.20</code> server-এ data পাঠানো হবে।</p><ol><li>Application destination হিসেবে server-এর IP ও service port নির্ধারণ করে</li><li>Host subnet mask দেখে বুঝে destination local subnet-এ নেই</li><li>তাই packet default gateway <code>192.168.1.1</code>-এর দিকে পাঠাতে হবে</li><li>Host ARP ব্যবহার করে gateway-এর MAC address খুঁজে</li><li>IP packet-টি Ethernet বা Wi-Fi frame-এর ভিতরে encapsulate হয়</li><li>Local switch frame-টি gateway interface-এ পৌঁছে দেয়</li><li>Router destination IP দেখে routing table থেকে next hop নির্বাচন করে</li><li>প্রতিটি router নতুন local frame তৈরি করে packet forward করে</li><li>Destination network-এর router packet server-এর local interface-এ পাঠায়</li><li>Server packet গ্রহণ করে, transport/application layer-এ data process করে</li><li>Response একই ধরনের layered process-এ client-এর দিকে ফিরে আসে</li></ol>',41)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-893",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20Client%20Host%0A%20%20%20%20participant%20G%20as%20Default%20Gateway%0A%20%20%20%20participant%20I%20as%20ISP%2FInternet%20Routers%0A%20%20%20%20participant%20S%20as%20Destination%20Server%0A%20%20%20%20C-%3E%3EC%3A%20Destination%20local%20subnet-%E0%A6%8F%20%E0%A6%95%E0%A6%BF%20%E0%A6%A8%E0%A6%BE%20%E0%A6%AF%E0%A6%BE%E0%A6%9A%E0%A6%BE%E0%A6%87%0A%20%20%20%20C-%3E%3EG%3A%20Local%20frame-%E0%A6%8F%E0%A6%B0%20%E0%A6%AD%E0%A6%BF%E0%A6%A4%E0%A6%B0%E0%A7%87%20IP%20packet%0A%20%20%20%20G-%3E%3EI%3A%20Routing%20table%20%E0%A6%85%E0%A6%A8%E0%A7%81%E0%A6%AF%E0%A6%BE%E0%A6%AF%E0%A6%BC%E0%A7%80%20forward%0A%20%20%20%20I-%3E%3EI%3A%20%E0%A6%8F%E0%A6%95%E0%A6%BE%E0%A6%A7%E0%A6%BF%E0%A6%95%20hop-%E0%A6%8F%20packet%20forward%0A%20%20%20%20I-%3E%3ES%3A%20Destination%20network-%E0%A6%8F%20packet%0A%20%20%20%20S--%3E%3EI%3A%20Response%20packet%0A%20%20%20%20I--%3E%3EG%3A%20Reverse%20path%0A%20%20%20%20G--%3E%3EC%3A%20Client-%E0%A6%8F%E0%A6%B0%20local%20frame%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[a(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=i('<h2 id="_13-real-world-example-—-browser-এ-একটি-website-খোলা" tabindex="-1">13. Real World Example — Browser-এ একটি Website খোলা <a class="header-anchor" href="#_13-real-world-example-—-browser-এ-একটি-website-খোলা" aria-label="Permalink to &quot;13. Real World Example — Browser-এ একটি Website খোলা&quot;">​</a></h2><p>আপনি browser-এ <code>https://example.com</code> লিখলে শুধু একটি কাজ হয় না; বহু network operation ধারাবাহিকভাবে ঘটে।</p><ol><li>Browser hostname <code>example.com</code>-এর IP জানতে DNS query করে</li><li>Host-এর local DNS cache বা configured DNS resolver উত্তর দেয়</li><li>Browser destination IP-এর port <code>443</code>-এ connection শুরু করে</li><li>Local host route দেখে packet default gateway-এ পাঠায়</li><li>Router ও ISP packet-কে Internet-এর বিভিন্ন network পার করে</li><li>Server firewall ও load balancer request গ্রহণ করে</li><li>HTTPS-এর জন্য encryption handshake হয়</li><li>Web server request process করে response পাঠায়</li><li>Browser response-এর data assemble করে page render করে</li></ol>',3)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-947",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BBrowser%3A%20URL%20%E0%A6%B2%E0%A7%87%E0%A6%96%E0%A6%BE%5D%20--%3E%20B%5BDNS%3A%20Hostname%20%E0%A6%A5%E0%A7%87%E0%A6%95%E0%A7%87%20IP%5D%0A%20%20%20%20B%20--%3E%20C%5BRoute%20decision%5D%0A%20%20%20%20C%20--%3E%20D%5BDefault%20Gateway%5D%0A%20%20%20%20D%20--%3E%20E%5BISP%20%E0%A6%93%20Internet%20Routers%5D%0A%20%20%20%20E%20--%3E%20F%5BServer%20%E0%A6%AC%E0%A6%BE%20Load%20Balancer%5D%0A%20%20%20%20F%20--%3E%20G%5BHTTPS%20Response%5D%0A%20%20%20%20G%20--%3E%20H%5BBrowser%20page%20render%5D%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[a(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=d("p",null,"এই journey-র প্রতিটি অংশ আলাদা failure তৈরি করতে পারে। DNS ঠিক থাকলেও route বন্ধ হতে পারে, route ঠিক থাকলেও port block হতে পারে, port খোলা থাকলেও application error দিতে পারে।",-1)),e[14]||(e[14]=d("h2",{id:"_14-mlops-llmops-এ-networking-এর-গুরুত্ব",tabindex:"-1"},[a("14. MLOps/LLMOps-এ Networking-এর গুরুত্ব "),d("a",{class:"header-anchor",href:"#_14-mlops-llmops-এ-networking-এর-গুরুত্ব","aria-label":'Permalink to "14. MLOps/LLMOps-এ Networking-এর গুরুত্ব"'},"​")],-1)),e[15]||(e[15]=d("p",null,"MLOps বা LLMOps platform-এ একাধিক service network-এর মাধ্যমে যুক্ত থাকে:",-1)),(o(),s(n,null,{default:t(()=>[l(r,{id:"mermaid-957",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20U%5BUser%2FAPI%20Client%5D%20--%3E%20G%5BAPI%20Gateway%5D%0A%20%20%20%20G%20--%3E%20A%5BModel%20API%5D%0A%20%20%20%20A%20--%3E%20V%5BVector%20Database%5D%0A%20%20%20%20A%20--%3E%20R%5BModel%20Registry%5D%0A%20%20%20%20A%20--%3E%20O%5BObject%20Storage%5D%0A%20%20%20%20A%20--%3E%20M%5BMonitoring%20Service%5D%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[a(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=i('<p>উদাহরণ হিসেবে:</p><ul><li>Inference API-কে model server-এর port-এ পৌঁছাতে হয়</li><li>RAG application-কে vector database-এর host ও port জানতে হয়</li><li>Training job-কে object storage ও experiment tracker-এ data পাঠাতে হয়</li><li>Monitoring agent metrics endpoint-এ network request করে</li><li>Container ও Kubernetes service-গুলোর মধ্যে DNS ও routing কাজ করে</li></ul><p>তাই model code সঠিক হলেও <code>Connection refused</code>, <code>Timeout</code>, <code>No route to host</code>, ভুল hostname বা firewall rule-এর কারণে পুরো pipeline ব্যর্থ হতে পারে।</p><h2 id="_15-common-mistakes-—-নতুনরা-যেসব-ভুল-করে" tabindex="-1">15. Common Mistakes — নতুনরা যেসব ভুল করে <a class="header-anchor" href="#_15-common-mistakes-—-নতুনরা-যেসব-ভুল-করে" aria-label="Permalink to &quot;15. Common Mistakes — নতুনরা যেসব ভুল করে&quot;">​</a></h2><ol><li><strong>IP Address-কে device-এর স্থায়ী পরিচয় ভাবা</strong> — DHCP বা network বদলালে host-এর IP বদলাতে পারে।</li><li><strong>Private IP দিয়ে Internet থেকে server access করার চেষ্টা করা</strong> — private address Internet-এ routable নয়।</li><li><strong><code>ping</code> সফল মানেই application ঠিক আছে ভাবা</strong> — ICMP কাজ করলেও TCP port বা application বন্ধ থাকতে পারে।</li><li><strong><code>localhost</code>-কে অন্য machine বা container ভাবা</strong> — <code>localhost</code> সবসময় request করা current host/interface-কে বোঝায়।</li><li><strong>Port ও IP একই জিনিস ভাবা</strong> — IP host চেনে, port host-এর ভিতরের service চেনে।</li><li><strong>একটি network মানেই Internet ভাবা</strong> — LAN, WAN এবং Internet-এর scope আলাদা।</li><li><strong>Router শুধু Internet-এর জন্য ব্যবহার হয় ভাবা</strong> — router যেকোনো আলাদা IP network-এর মধ্যে packet forward করতে পারে।</li><li><strong>High latency-কে সবসময় bandwidth সমস্যা ভাবা</strong> — latency, throughput, packet loss ও congestion আলাদা বিষয়।</li><li><strong>শুধু application log দেখে network সমস্যা সমাধান করা</strong> — interface, route, DNS, port এবং firewall আলাদা স্তরে পরীক্ষা করা দরকার।</li><li><strong>IP hardcode করে configuration স্থির ভাবা</strong> — production-এ DNS বা service discovery ব্যবহার করলে endpoint পরিবর্তন সহজ হয়।</li></ol><h2 id="_16-best-practices" tabindex="-1">16. Best Practices <a class="header-anchor" href="#_16-best-practices" aria-label="Permalink to &quot;16. Best Practices&quot;">​</a></h2><ul><li>Host, interface, IP, subnet, gateway ও DNS-এর তথ্য documentation-এ পরিষ্কার রাখুন</li><li>Production service-এর জন্য meaningful DNS name বা service discovery ব্যবহার করুন</li><li>Network range পরিকল্পনা করার সময় ভবিষ্যৎ growth ও subnet বিভাজন বিবেচনা করুন</li><li>Service-to-service traffic-এ least privilege firewall rule ব্যবহার করুন</li><li>গুরুত্বপূর্ণ service-এর জন্য health check, timeout, retry ও circuit breaker পরিকল্পনা করুন</li><li><code>ping</code>, <code>traceroute</code>, <code>nslookup</code>/<code>dig</code>, <code>ss</code>/<code>netstat</code> এবং packet capture-এর উদ্দেশ্য আলাদা করে শিখুন</li><li>Public service expose করার আগে authentication, encryption ও firewall policy নিশ্চিত করুন</li><li>একই network-এ সব service না রেখে প্রয়োজন অনুযায়ী segmentation করুন</li><li>IPv4-এর পাশাপাশি IPv6 readiness যাচাই করুন</li><li>Network observability-এর জন্য latency, error rate, packet loss, connection count ও throughput monitor করুন</li><li>Configuration-এ IP hardcode না করে environment-specific DNS বা service endpoint ব্যবহার করুন</li></ul><div class="warning custom-block"><p class="custom-block-title">Troubleshooting-এর সঠিক ক্রম</p><p>একসাথে সব configuration বদলাবেন না। প্রথমে link/interface, তারপর local IP, route, DNS, port connectivity এবং শেষে application protocol পরীক্ষা করুন। এতে root cause দ্রুত আলাদা করা যায়।</p></div><h2 id="_17-interview-questions" tabindex="-1">17. Interview Questions <a class="header-anchor" href="#_17-interview-questions" aria-label="Permalink to &quot;17. Interview Questions&quot;">​</a></h2><h3 id="প্রশ্ন-১-host-কী" tabindex="-1">প্রশ্ন ১: Host কী? <a class="header-anchor" href="#প্রশ্ন-১-host-কী" aria-label="Permalink to &quot;প্রশ্ন ১: Host কী?&quot;">​</a></h3><p><strong>উত্তর:</strong> Host হলো এমন কোনো network-connected device বা endpoint যা data পাঠাতে বা গ্রহণ করতে পারে। Computer, phone, server, printer, VM এবং container host-এর উদাহরণ। Host client, server বা দুটো ভূমিকাতেই কাজ করতে পারে।</p><h3 id="প্রশ্ন-২-network-ও-internet-এর-মধ্যে-পার্থক্য-কী" tabindex="-1">প্রশ্ন ২: Network ও Internet-এর মধ্যে পার্থক্য কী? <a class="header-anchor" href="#প্রশ্ন-২-network-ও-internet-এর-মধ্যে-পার্থক্য-কী" aria-label="Permalink to &quot;প্রশ্ন ২: Network ও Internet-এর মধ্যে পার্থক্য কী?&quot;">​</a></h3><p><strong>উত্তর:</strong> Network হলো যোগাযোগের জন্য সংযুক্ত দুই বা ততোধিক host-এর একটি logical বা physical group। Internet হলো বহু স্বাধীন network, ISP এবং backbone-এর interconnected global system। তাই Internet একটি network নয়; এটি network-এর network।</p><h3 id="প্রশ্ন-৩-ip-address-এর-কাজ-কী" tabindex="-1">প্রশ্ন ৩: IP Address-এর কাজ কী? <a class="header-anchor" href="#প্রশ্ন-৩-ip-address-এর-কাজ-কী" aria-label="Permalink to &quot;প্রশ্ন ৩: IP Address-এর কাজ কী?&quot;">​</a></h3><p><strong>উত্তর:</strong> IP Address network layer-এ source ও destination host বা interface শনাক্ত করে এবং router-কে packet কোন network-এর দিকে পাঠাতে হবে তা নির্ধারণে সাহায্য করে। IP logical address; এটি MAC address বা application port-এর বিকল্প নয়।</p><h3 id="প্রশ্ন-৪-একই-host-এর-ip-address-ও-port-কেন-দুটোই-দরকার" tabindex="-1">প্রশ্ন ৪: একই host-এর IP Address ও Port কেন দুটোই দরকার? <a class="header-anchor" href="#প্রশ্ন-৪-একই-host-এর-ip-address-ও-port-কেন-দুটোই-দরকার" aria-label="Permalink to &quot;প্রশ্ন ৪: একই host-এর IP Address ও Port কেন দুটোই দরকার?&quot;">​</a></h3><p><strong>উত্তর:</strong> IP Address host বা machine শনাক্ত করে, আর Port সেই host-এর নির্দিষ্ট service শনাক্ত করে। যেমন <code>203.0.113.20:443</code>-এ <code>203.0.113.20</code> হলো server host এবং <code>443</code> হলো HTTPS service-এর endpoint।</p><h2 id="_18-summary" tabindex="-1">18. Summary <a class="header-anchor" href="#_18-summary" aria-label="Permalink to &quot;18. Summary&quot;">​</a></h2><ul><li><strong>Host</strong> হলো network traffic পাঠানো বা গ্রহণ করা device বা endpoint।</li><li><strong>Client</strong> request করে এবং <strong>Server</strong> response দেয়; এই role context অনুযায়ী বদলাতে পারে।</li><li><strong>IP Address</strong> host-এর logical network identity এবং packet delivery-এর ভিত্তি।</li><li><strong>IPv4</strong> 32-bit, আর <strong>IPv6</strong> 128-bit addressing ব্যবহার করে।</li><li><strong>Private IP</strong> local network-এ ব্যবহৃত হয়; Internet-এ direct route করা যায় না।</li><li><strong>Network</strong> হলো connected host-এর logical group; <strong>Subnet</strong> বড় network-কে ছোট segment-এ ভাগ করে।</li><li><strong>Internet</strong> হলো interconnected networks-এর বিশ্বব্যাপী system।</li><li>Data packet আকারে layer পেরিয়ে router ও বিভিন্ন hop-এর মাধ্যমে destination-এ যায়।</li><li>IP host চেনে, MAC local link-এর interface চেনে, আর port নির্দিষ্ট service চেনে।</li><li><code>ping</code> reachability, <code>traceroute</code> path, <code>ss</code>/<code>netstat</code> listening state এবং <code>nslookup</code>/<code>dig</code> DNS পরীক্ষা করতে সাহায্য করে।</li></ul><h2 id="_19-পরবর্তী-ধাপ" tabindex="-1">19. পরবর্তী ধাপ <a class="header-anchor" href="#_19-পরবর্তী-ধাপ" aria-label="Permalink to &quot;19. পরবর্তী ধাপ&quot;">​</a></h2><p>এখন পরবর্তী গুরুত্বপূর্ণ বিষয় হলো <strong>OSI Model</strong> — যেখানে network communication-কে সাতটি layer-এ ভাগ করে প্রতিটি layer-এর কাজ, protocol এবং troubleshooting boundary বিস্তারিতভাবে বোঝা হবে।</p>',21))])}const I=c(u,[["render",k]]);export{P as __pageData,I as default};
